<?php
namespace App\Services;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
final class ExamAccess {
 public function __construct(public SchoolAccess $access){}
 public function fail(string $m):never{throw ValidationException::withMessages(['exam'=>$m]);}
 public function can(Request $r,string $p):bool{$key='exam.permission.'.$p;if(!$r->attributes->has($key))$r->attributes->set($key,$this->access->can($r,$p));return $r->attributes->get($key);}
 public function context(Request $r):array{if($r->attributes->has('exam.context'))return $r->attributes->get('exam.context');abort_unless($this->can($r,'tests.enter_marks')||$this->can($r,'tests.publish')||$this->can($r,'tests.view'),403);$m=$this->access->membership($r);$period=LicenseService::period($m->school_id);if($period)abort_unless(in_array('tests_results',json_decode($period->modules,true)??[],true),403,'Tests/results are not included in this school license.');$campuses=in_array('owner',$this->access->roles($m),true)?DB::table('campuses')->where('school_id',$m->school_id)->pluck('id')->all():array_map(fn($c)=>$c->id,$this->access->campuses($m));$context=[(int)$m->school_id,$m,$campuses];$r->attributes->set('exam.context',$context);return $context;}
 public function assignments(object $m){return DB::table('teacher_assignments as a')->join('staff_profiles as p','p.id','=','a.staff_profile_id')->where('a.school_id',$m->school_id)->where('p.membership_id',$m->id)->where('p.status','active');}
 public function sections(Request $r){[$sid,$m,$campuses]=$this->context($r);$q=DB::table('sections as s')->join('classes as c','c.id','=','s.class_id')->join('campuses as p','p.id','=','s.campus_id')->join('academic_sessions as y','y.id','=','s.academic_session_id')->where('s.school_id',$sid)->whereIn('s.campus_id',$campuses);if(!$this->can($r,'tests.publish'))$q->whereIn('s.id',$this->assignments($m)->select('a.section_id'));return $q->select('s.*','c.name as class_name','p.name as campus_name','p.status as campus_status','y.name as session_name','y.starts_on as session_start','y.ends_on as session_end','y.status as session_status');}
 public function section(Request $r,int $id):object{return $this->sections($r)->where('s.id',$id)->first()??abort(404);}
 public function active(object $s):void{if($s->session_status!=='active'||$s->campus_status!=='active')$this->fail('Archived campus/session: exam content is read-only.');}
 public function classReports(Request $r,object $s):bool{[, $m]=$this->context($r);return $this->can($r,'tests.publish')||$this->assignments($m)->where('a.section_id',$s->id)->where('a.is_class_teacher',true)->exists();}
 public function subject(Request $r,object $s,int $id,bool $write=false):void{[$sid,$m]=$this->context($r);abort_unless(DB::table('section_subjects')->where('school_id',$sid)->where('section_id',$s->id)->where('subject_id',$id)->exists(),404);$publisher=$this->can($r,'tests.publish');$q=$this->assignments($m)->where('a.section_id',$s->id);if($write){abort_unless($this->can($r,'tests.enter_marks')&&($publisher||$q->where('a.subject_id',$id)->exists()),403,'Only the assigned subject teacher can enter these marks.');}else abort_unless($publisher||$q->where(fn($q)=>$q->where('a.subject_id',$id)->orWhere('a.is_class_teacher',true))->exists(),404);}
 public function test(Request $r,int $id,bool $write=false):array{[$sid]=$this->context($r);$t=DB::table('tests')->where('school_id',$sid)->where('id',$id)->first()??abort(404);$s=$this->section($r,$t->section_id);$this->subject($r,$s,$t->subject_id,$write);if($write)$this->active($s);return [$t,$s];}
 public function roster(int $sid,int $section,string $date){$rows=DB::table('enrollments as e')->join('students as s','s.id','=','e.student_id')->where('e.school_id',$sid)->where('e.section_id',$section)->where('e.starts_on','<=',$date)->where(fn($q)=>$q->whereNull('e.ends_on')->orWhere('e.ends_on','>=',$date))->orderBy('e.roll_no')->orderBy('s.first_name')->get(['e.id as enrollment_id','e.student_id','e.roll_no','s.first_name','s.last_name','s.admission_no']);if($rows->pluck('student_id')->unique()->count()!==$rows->count())$this->fail('Overlapping enrollments need review before results can be saved.');return $rows;}
 public function cents(mixed $v):int{if(!is_numeric($v)||!preg_match('/^\d{1,6}(?:\.\d{1,2})?$/D',(string)$v))$this->fail('Use non-negative marks with at most two decimals (maximum 100000).');$parts=explode('.',(string)$v);$n=(int)$parts[0]*100+(int)str_pad($parts[1]??'',2,'0');if($n>10000000)$this->fail('Marks cannot exceed 100000.');return $n;}
 public function number(int $c):string{return number_format($c/100,2,'.','');}
 public function scheme(int $sid,int $id):object{$g=DB::table('grading_schemes')->where('school_id',$sid)->where('id',$id)->first()??abort(404);$g->rules=json_decode($g->rules,true);if(!isset($g->rules['bands'],$g->rules['passing_percent'])||!in_array($g->rounding_policy,['two_decimals','whole_percent'],true)||!in_array($g->tie_policy,['competition','dense','none'],true))$this->fail('Legacy grading scheme needs review. Create a supported version for new assessments.');return $g;}
 public function percent(int $earned,int $maximum,object $g):int{$bp=$maximum?intdiv($earned*10000+intdiv($maximum,2),$maximum):0;return $g->rounding_policy==='whole_percent'?intdiv($bp+50,100)*100:$bp;}
 public function grade(int $bp,object $g):string{foreach($g->rules['bands'] as $b)if($bp>=$this->cents($b['min_percent']))return $b['label'];return '—';}
 public function sharing(Request $r):bool{[$sid]=$this->context($r);$period=LicenseService::period($sid);return $this->can($r,'reports.confirm_share')&&(!$period||in_array('manual_whatsapp_sharing',json_decode($period->modules,true)??[],true));}
 public function lock(Request $r):int{[$sid]=$this->context($r);DB::table('schools')->where('id',$sid)->lockForUpdate()->first();return $sid;}
}
